package com.gimprogresstracker;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(GIMProgressTrackerConfig.GROUP)
public interface GIMProgressTrackerConfig extends Config
{
	String GROUP = "gim-progress-tracker";

	@ConfigSection(
		name = "Display",
		description = "What the plugin draws on-screen",
		position = 0
	)
	String displaySection = "display";

	@ConfigSection(
		name = "Integrations",
		description = "Optional features that integrate with other plugins or the GIM group",
		position = 1,
		closedByDefault = true
	)
	String integrationsSection = "integrations";

	@ConfigSection(
		name = "Team sync",
		description = "Local file-based sync with GIM teammates",
		position = 2,
		closedByDefault = true
	)
	String syncSection = "sync";

	@ConfigSection(
		name = "Developer (experimental)",
		description = "Experimental features that are not fully tested. Use at your own risk.",
		position = 3,
		closedByDefault = true
	)
	String developerSection = "developer";

	@ConfigItem(
		keyName = "guideFilePath",
		name = "Guide file path",
		description = "Path to a guide .json file. Prefer the panel's Import button.",
		position = 0,
		section = displaySection
	)
	default String guideFilePath()
	{
		return "";
	}

	@ConfigItem(
		keyName = "showMinimapArrow",
		name = "Show minimap arrow",
		description = "Display a marker on the minimap pointing to the current step",
		position = 1,
		section = displaySection
	)
	default boolean showMinimapArrow()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showWorldMapArrow",
		name = "Show world map arrow",
		description = "Display a marker on the world map at the current step's location",
		position = 2,
		section = displaySection
	)
	default boolean showWorldMapArrow()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSceneHighlight",
		name = "Highlight destination tile",
		description = "Outline the current step's destination tile in the game world when it is in view",
		position = 3,
		section = displaySection
	)
	default boolean showSceneHighlight()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightColor",
		name = "Highlight color",
		description = "Color used for the destination tile highlight",
		position = 4,
		section = displaySection
	)
	default Color highlightColor()
	{
		return new Color(0, 200, 220);
	}

	@ConfigItem(
		keyName = "autoSkipBanked",
		name = "Auto-skip banked items",
		description = "Automatically mark a step skippable when its required items are present in the group storage (Phase 2)",
		position = 1,
		section = integrationsSection
	)
	default boolean autoSkipBanked()
	{
		return false;
	}

	@ConfigItem(
		keyName = "useShortestPath",
		name = "Shortest path to next step (experimental)",
		description = "Send the current step's destination to the Shortest Path plugin. The path clears when you arrive and reappears on the next step. Works with any of Shortest Path's display styles.",
		warning = "Experimental and not fully tested. Requires the Shortest Path plugin from the Plugin Hub. Writes to that plugin via its inter-plugin messaging API.",
		position = 0,
		section = developerSection
	)
	default boolean useShortestPath()
	{
		return false;
	}

	@ConfigItem(
		keyName = "sharedFolderPath",
		name = "Shared folder path",
		description = "Folder used to share progress with teammates (e.g. a Dropbox subfolder)",
		position = 0,
		section = syncSection
	)
	default String sharedFolderPath()
	{
		return "";
	}

	@ConfigItem(
		keyName = "autoExportProgress",
		name = "Auto-export progress",
		description = "Write a copy of your progress to the shared folder whenever a step changes",
		position = 1,
		section = syncSection
	)
	default boolean autoExportProgress()
	{
		return false;
	}
}

package com.gimprogresstracker;

import com.gimprogresstracker.model.Location;
import com.gimprogresstracker.model.StepEntry;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import java.util.Optional;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws a tile highlight on the destination of the current step when it is in the loaded scene.
 */
public class GIMProgressTrackerOverlay extends Overlay
{
	private static final Stroke OUTLINE_STROKE = new BasicStroke(2f);

	private final Client client;
	private final ProgressTracker tracker;
	private final GIMProgressTrackerConfig config;

	@Inject
	GIMProgressTrackerOverlay(Client client, ProgressTracker tracker, GIMProgressTrackerConfig config)
	{
		this.client = client;
		this.tracker = tracker;
		this.config = config;
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.DYNAMIC);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Optional<StepEntry> currentOpt = tracker.getCurrentStep();
		if (!currentOpt.isPresent())
		{
			return null;
		}
		Location loc = currentOpt.get().getStep().getLocation();
		if (loc == null)
		{
			return null;
		}

		WorldPoint target = new WorldPoint(loc.getX(), loc.getY(), loc.getPlane());
		if (target.getPlane() != client.getTopLevelWorldView().getPlane())
		{
			return null;
		}

		LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), target);
		if (lp == null)
		{
			return null;
		}

		Polygon poly = Perspective.getCanvasTilePoly(client, lp);
		if (poly == null)
		{
			return null;
		}

		Color highlight = config.highlightColor();
		Color fill = new Color(highlight.getRed(), highlight.getGreen(), highlight.getBlue(), 50);

		Stroke prev = graphics.getStroke();
		graphics.setStroke(OUTLINE_STROKE);
		graphics.setColor(highlight);
		graphics.draw(poly);
		graphics.setColor(fill);
		graphics.fill(poly);
		graphics.setStroke(prev);

		return null;
	}
}

package com.gimprogresstracker;

import com.gimprogresstracker.model.Guide;
import com.gimprogresstracker.model.ItemStatus;
import com.gimprogresstracker.model.Location;
import com.gimprogresstracker.model.RequiredItem;
import com.gimprogresstracker.model.StepEntry;
import com.gimprogresstracker.ui.GIMProgressTrackerPanel;
import com.gimprogresstracker.ui.PanelIcons;
import com.gimprogresstracker.ui.TeammatesPanel;
import com.gimprogresstracker.util.GuideImporter;
import com.gimprogresstracker.util.PluginPaths;
import com.gimprogresstracker.util.ProgressStore;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.Varbits;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.Notifier;
import net.runelite.client.util.LinkBrowser;

@Slf4j
@PluginDescriptor(
	name = "Vibe Steps Progress Tracker",
	description = "Step-by-step Group Ironman progress tracker with importable guides",
	tags = {"vibe", "steps", "group", "ironman", "gim", "guide", "tracker", "progress"}
)
public class GIMProgressTrackerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private WorldMapPointManager worldMapPointManager;

	@Inject
	private GIMProgressTrackerConfig config;

	@Inject
	private GIMProgressTrackerOverlay overlay;

	@Inject
	private ProgressTracker tracker;

	@Inject
	private ProgressStore progressStore;

	@Inject
	private GuideImporter guideImporter;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private Notifier notifier;

	@Inject
	private EventBus eventBus;

	private GIMProgressTrackerPanel panel;
	private TeammatesPanel teammatesPanel;
	private NavigationButton navButton;
	private NavigationButton teammatesNavButton;
	private WorldMapPoint mapPoint;
	private WorldMapPoint teammateMapPoint;
	private Runnable trackerListener;
	private BufferedImage mapPointIcon;

	// Item names resolved on the client thread and cached so the EDT can render
	// item rows without touching client APIs.
	private final ConcurrentHashMap<Integer, String> itemNameCache = new ConcurrentHashMap<>();

	private volatile boolean isGroupIronman = false;

	// Pre-canonicalized item ID → quantity maps, built on the client thread so
	// checkItemStatus can do pure map lookups from any thread (including the EDT).
	private volatile Map<Integer, Integer> cachedInventory = Collections.emptyMap();
	private volatile Map<Integer, Integer> cachedEquipment = Collections.emptyMap();
	private volatile Map<Integer, Integer> cachedBank = Collections.emptyMap();
	private volatile Map<Integer, Integer> cachedGimBank = Collections.emptyMap();

	// Last observed player tile, used by the Shortest Path integration to detect
	// teleports (single-tick position deltas larger than running speed) and resend
	// the path target so Shortest Path recomputes from the new tile.
	private WorldPoint lastPlayerLocation = null;

	// Skill name → real level, updated on login and StatChanged. Keyed by Skill.name()
	// so the EDT can read it without touching the client API.
	private final ConcurrentHashMap<String, Integer> cachedSkillLevels = new ConcurrentHashMap<>();

	@Override
	protected void startUp() throws Exception
	{
		mapPointIcon = buildMapPointIcon(config.highlightColor());

		panel = new GIMProgressTrackerPanel(tracker, this::loadGuideFromFile, this::resetProgress,
			this::isQuestHelperInstalled, this::openQuestHelperForQuest, this::openWikiForQuest,
			itemManager, this::checkItemStatus,
			id -> itemNameCache.getOrDefault(id, "Item #" + id),
			() -> !cachedBank.isEmpty(),
			() -> !cachedGimBank.isEmpty(),
			() -> isGroupIronman,
			skill -> cachedSkillLevels.getOrDefault(skill.name(), 1),
			this::openWorldMapAt,
			this::isPathTrackingEnabled,
			this::togglePathTracking);

		navButton = NavigationButton.builder()
			.tooltip("Vibe Steps Progress Tracker")
			.icon(PanelIcons.navIcon(GIMProgressTrackerPlugin.class))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		teammatesPanel = new TeammatesPanel(tracker, progressStore, config::sharedFolderPath,
			this::showTeammateMapPoint);
		teammatesNavButton = NavigationButton.builder()
			.tooltip("Vibe Steps – Teammates")
			.icon(PanelIcons.teammatesIcon())
			.priority(8)
			.panel(teammatesPanel)
			.build();
		clientToolbar.addNavigation(teammatesNavButton);

		overlayManager.add(overlay);

		trackerListener = this::onTrackerChanged;
		tracker.addListener(trackerListener);

		// Try to pull a player name immediately in case the client is already logged in.
		// Fall back to a "default" profile so progress tracking works pre-login (e.g. in the
		// dev client). Once the real account logs in, setPlayerName will swap to that profile.
		String name = currentPlayerName();
		tracker.setPlayerName(name != null ? name : "default");

		// Load the configured guide, if any.
		loadGuideFromConfig();
	}

	@Override
	protected void shutDown() throws Exception
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		if (teammatesNavButton != null)
		{
			clientToolbar.removeNavigation(teammatesNavButton);
			teammatesNavButton = null;
		}
		teammatesPanel = null;
		overlayManager.remove(overlay);

		if (trackerListener != null)
		{
			tracker.removeListener(trackerListener);
			trackerListener = null;
		}
		clearWorldMapPoint();
		clearTeammateMapPoint();
		if (config.useShortestPath())
		{
			clearShortestPath();
		}

		// Persist a final time, then drop in-memory state.
		tracker.persist();
		tracker.setGuide(null);
		panel = null;
	}

	@Provides
	GIMProgressTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GIMProgressTrackerConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			String name = currentPlayerName();
			if (name != null)
			{
				tracker.setPlayerName(name);
			}
			// Varbit 1777 (ACCOUNT_TYPE): 4=Group Ironman, 5=Hardcore Group Ironman, 6=Unranked Group Ironman
			int acctType = client.getVarbitValue(Varbits.ACCOUNT_TYPE);
			isGroupIronman = acctType == 4 || acctType == 5 || acctType == 6;
			cacheAllSkillLevels();
		}
		else
		{
			// Avoid treating the post-relog position as a teleport from wherever we
			// were last logged out.
			lastPlayerLocation = null;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!config.useShortestPath() || !isShortestPathInstalled())
		{
			lastPlayerLocation = null;
			return;
		}
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			lastPlayerLocation = null;
			return;
		}
		WorldPoint current = local.getWorldLocation();
		WorldPoint previous = lastPlayerLocation;
		lastPlayerLocation = current;
		// Resend the path whenever the player tile changes (walk, run, teleport,
		// stairs/plane). Shortest Path only auto-recomputes when the player goes
		// off-path, so without this the displayed path "tail" wouldn't shrink as
		// the player walks toward the target.
		if (previous != null && !current.equals(previous))
		{
			maybeSendShortestPathTarget();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		if (skill != null && skill != Skill.OVERALL)
		{
			cachedSkillLevels.put(skill.name(), event.getLevel());
		}
	}

	private void cacheAllSkillLevels()
	{
		clientThread.invoke(() ->
		{
			for (Skill skill : Skill.values())
			{
				if (skill != Skill.OVERALL)
				{
					cachedSkillLevels.put(skill.name(), client.getRealSkillLevel(skill));
				}
			}
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!GIMProgressTrackerConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		switch (event.getKey())
		{
			case "guideFilePath":
				loadGuideFromConfig();
				break;
			case "highlightColor":
				mapPointIcon = buildMapPointIcon(config.highlightColor());
				refreshWorldMapPoint();
				break;
			case "showWorldMapArrow":
				refreshWorldMapPoint();
				break;
			case "useShortestPath":
				if (config.useShortestPath())
				{
					if (!isShortestPathInstalled())
					{
						configManager.setConfiguration(GIMProgressTrackerConfig.GROUP, "useShortestPath", false);
						SwingUtilities.invokeLater(() ->
							javax.swing.JOptionPane.showMessageDialog(panel,
								"The Shortest Path plugin must be installed and enabled before this toggle can be turned on.\n"
									+ "Install it from the Plugin Hub, enable it, then re-enable this option.",
								"Vibe Steps Progress Tracker", javax.swing.JOptionPane.WARNING_MESSAGE));
						break;
					}
					maybeSendShortestPathTarget();
				}
				else
				{
					clearShortestPath();
				}
				if (panel != null)
				{
					panel.refresh();
				}
				break;
			default:
				// other keys are read on demand by the overlay / panel; no action needed
		}
	}

	private void onTrackerChanged()
	{
		scheduleItemNameCaching();
		if (panel != null)
		{
			panel.refresh();
		}
		refreshWorldMapPoint();
		maybeSendShortestPathTarget();
		maybeAutoExport();
	}

	private void scheduleItemNameCaching()
	{
		Optional<StepEntry> stepOpt = tracker.getCurrentStep();
		if (!stepOpt.isPresent())
		{
			return;
		}
		List<RequiredItem> items = stepOpt.get().getStep().getRequiredItems();
		if (items.isEmpty())
		{
			return;
		}
		boolean allCached = items.stream().allMatch(i -> itemNameCache.containsKey(i.getItemId()));
		if (allCached)
		{
			return;
		}
		clientThread.invoke(() ->
		{
			boolean anyNew = false;
			for (RequiredItem item : items)
			{
				if (!itemNameCache.containsKey(item.getItemId()))
				{
					try
					{
						net.runelite.api.ItemComposition comp = itemManager.getItemComposition(item.getItemId());
						String name = comp.getName();
						if (name != null && !name.equals("null") && !name.isEmpty())
						{
							itemNameCache.put(item.getItemId(), name);
							anyNew = true;
						}
					}
					catch (Exception ignored)
					{
					}
				}
			}
			if (anyNew && panel != null)
			{
				panel.refresh();
			}
		});
	}

	private static final String DEFAULT_GUIDE_RESOURCE = "/guides/bruhsailer-guide.json";

	private void loadGuideFromConfig()
	{
		String pathStr = config.guideFilePath();
		if (pathStr == null || pathStr.trim().isEmpty())
		{
			loadDefaultGuide();
			return;
		}
		loadGuideFromFile(Paths.get(pathStr.trim()));
	}

	private void loadDefaultGuide()
	{
		try
		{
			Guide guide = guideImporter.loadFromResource(DEFAULT_GUIDE_RESOURCE);
			tracker.setGuide(guide);
			log.debug("Loaded bundled default guide '{}'", guide.getGuideName());
		}
		catch (IOException e)
		{
			log.warn("Failed to load bundled default guide: {}", e.getMessage());
		}
	}

	private void loadGuideFromFile(Path file)
	{
		try
		{
			Guide guide = guideImporter.loadFromFile(file);
			tracker.setGuide(guide);
			log.debug("Loaded guide '{}' from {}", guide.getGuideName(), file);

			// Persist the path so the plugin reloads this guide on next startup. The
			// equality check prevents a feedback loop with our own onConfigChanged.
			String resolved = file.toAbsolutePath().toString();
			if (!resolved.equals(config.guideFilePath()))
			{
				configManager.setConfiguration(GIMProgressTrackerConfig.GROUP, "guideFilePath", resolved);
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to load guide from {}: {}", file, e.getMessage());
			SwingUtilities.invokeLater(() ->
				javax.swing.JOptionPane.showMessageDialog(panel,
					"Could not load guide:\n" + e.getMessage(),
					"Vibe Steps Progress Tracker", javax.swing.JOptionPane.ERROR_MESSAGE));
		}
	}

	private void resetProgress()
	{
		tracker.reset();
	}

	private void refreshWorldMapPoint()
	{
		clearWorldMapPoint();
		if (!config.showWorldMapArrow())
		{
			return;
		}
		Optional<StepEntry> currentOpt = tracker.getCurrentStep();
		if (!currentOpt.isPresent())
		{
			return;
		}
		Location loc = currentOpt.get().getStep().getLocation();
		if (loc == null)
		{
			return;
		}
		WorldPoint wp = new WorldPoint(loc.getX(), loc.getY(), loc.getPlane());
		mapPoint = WorldMapPoint.builder()
			.worldPoint(wp)
			.image(mapPointIcon)
			.snapToEdge(true)
			.jumpOnClick(true)
			.name("Vibe Steps step " + currentOpt.get().getStep().getId())
			.build();
		worldMapPointManager.add(mapPoint);
	}

	private void clearWorldMapPoint()
	{
		if (mapPoint != null)
		{
			worldMapPointManager.remove(mapPoint);
			mapPoint = null;
		}
	}

	private void openWorldMapAt(Location loc)
	{
		refreshWorldMapPoint();
		WorldPoint wp = new WorldPoint(loc.getX(), loc.getY(), loc.getPlane());
		clientThread.invoke(() -> client.getWorldMap().setWorldMapPositionTarget(wp));
	}

	private void showTeammateMapPoint(Location loc)
	{
		clearTeammateMapPoint();
		WorldPoint wp = new WorldPoint(loc.getX(), loc.getY(), loc.getPlane());
		teammateMapPoint = WorldMapPoint.builder()
			.worldPoint(wp)
			.image(buildMapPointIcon(new Color(60, 140, 230)))
			.snapToEdge(true)
			.jumpOnClick(true)
			.name("Teammate step location")
			.build();
		worldMapPointManager.add(teammateMapPoint);
	}

	private void clearTeammateMapPoint()
	{
		if (teammateMapPoint != null)
		{
			worldMapPointManager.remove(teammateMapPoint);
			teammateMapPoint = null;
		}
	}

	private void maybeAutoExport()
	{
		if (!config.autoExportProgress())
		{
			return;
		}
		String folder = config.sharedFolderPath();
		if (folder == null || folder.trim().isEmpty())
		{
			return;
		}
		if (tracker.getProgress() == null)
		{
			return;
		}
		Path dir = Paths.get(folder.trim());
		if (!Files.isDirectory(dir))
		{
			log.debug("Shared folder does not exist: {}", dir);
			return;
		}
		String fname = PluginPaths.sanitizeForFilename(tracker.getProgress().getPlayerName()) + "_progress.json";

		// Snapshot current step so teammates can display it regardless of which guide they have loaded.
		Optional<StepEntry> currentStep = tracker.getCurrentStep();
		if (currentStep.isPresent())
		{
			StepEntry entry = currentStep.get();
			tracker.getProgress().setCurrentStepBreadcrumb(
				entry.getChapter().getName() + " › " + entry.getSection().getName());
			tracker.getProgress().setCurrentStepTldr(entry.getStep().getTldr());
			tracker.getProgress().setCurrentStepDescription(entry.getStep().getDescription());
			tracker.getProgress().setCurrentStepLocation(entry.getStep().getLocation());
		}
		else
		{
			tracker.getProgress().setCurrentStepBreadcrumb(null);
			tracker.getProgress().setCurrentStepTldr(null);
			tracker.getProgress().setCurrentStepDescription(null);
			tracker.getProgress().setCurrentStepLocation(null);
		}

		try
		{
			progressStore.exportTo(tracker.getProgress(), dir.resolve(fname));
		}
		catch (IOException e)
		{
			log.debug("Failed to export progress to shared folder", e);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		boolean relevant = false;
		if (id == InventoryID.INVENTORY.getId())
		{
			cachedInventory = buildItemMap(event.getItemContainer().getItems());
			relevant = true;
		}
		if (id == InventoryID.EQUIPMENT.getId())
		{
			cachedEquipment = buildItemMap(event.getItemContainer().getItems());
			relevant = true;
		}
		if (id == InventoryID.BANK.getId())
		{
			cachedBank = buildItemMap(event.getItemContainer().getItems());
			relevant = true;
		}
		if (id == InventoryID.GROUP_STORAGE.getId())
		{
			cachedGimBank = buildItemMap(event.getItemContainer().getItems());
			relevant = true;
		}
		if (relevant && panel != null)
		{
			panel.refresh();
		}
	}

	private Map<Integer, Integer> buildItemMap(Item[] items)
	{
		if (items == null)
		{
			return Collections.emptyMap();
		}
		Map<Integer, Integer> map = new HashMap<>();
		for (Item item : items)
		{
			// Skip empty bank slots (-1) and placeholders (quantity 0). Placeholders
			// remain in the personal bank when items get moved to group storage; without
			// this filter, canonicalize() would still register them and the item would
			// look "available" with quantity 0 — confusing if we later compare quantities.
			if (item.getId() == -1 || item.getQuantity() <= 0)
			{
				continue;
			}
			int canonical = itemManager.canonicalize(item.getId());
			map.merge(canonical, item.getQuantity(), Integer::sum);
		}
		return map;
	}

	private ItemStatus checkItemStatus(RequiredItem required)
	{
		int itemId = required.getItemId();
		int needed = required.getQuantity();
		if (cachedInventory.getOrDefault(itemId, 0) >= needed)
		{
			return ItemStatus.IN_INVENTORY;
		}
		if (cachedEquipment.getOrDefault(itemId, 0) >= needed)
		{
			return ItemStatus.IN_EQUIPMENT;
		}
		if (cachedGimBank.getOrDefault(itemId, 0) >= needed)
		{
			return ItemStatus.IN_GIM_BANK;
		}
		if (cachedBank.getOrDefault(itemId, 0) >= needed)
		{
			return ItemStatus.IN_BANK;
		}
		return ItemStatus.NOT_FOUND;
	}

	private boolean isQuestHelperInstalled()
	{
		return pluginManager.getPlugins().stream()
			.anyMatch(p -> "QuestHelperPlugin".equals(p.getClass().getSimpleName())
				&& pluginManager.isPluginEnabled(p));
	}

	// --- Shortest Path integration (experimental) ---------------------------
	// Sends the current step's destination tile to the Shortest Path plugin via
	// its inter-plugin PluginMessage API. Shortest Path auto-clears its own path
	// when the player reaches the tile, so we only need to push a new target
	// when our step advances and clear when the feature is disabled.

	private static final String SHORTEST_PATH_NAMESPACE = "shortestpath";
	private static final String SHORTEST_PATH_MSG_PATH = "path";
	private static final String SHORTEST_PATH_MSG_CLEAR = "clear";
	private static final String SHORTEST_PATH_KEY_START = "start";
	private static final String SHORTEST_PATH_KEY_TARGET = "target";

	private boolean isShortestPathInstalled()
	{
		return pluginManager.getPlugins().stream()
			.anyMatch(p -> "ShortestPathPlugin".equals(p.getClass().getSimpleName())
				&& pluginManager.isPluginEnabled(p));
	}

	private void maybeSendShortestPathTarget()
	{
		if (!config.useShortestPath() || !isShortestPathInstalled())
		{
			return;
		}
		Optional<StepEntry> currentOpt = tracker.getCurrentStep();
		Location loc = currentOpt.map(s -> s.getStep().getLocation()).orElse(null);
		if (loc == null)
		{
			clearShortestPath();
			return;
		}
		WorldPoint target = new WorldPoint(loc.getX(), loc.getY(), loc.getPlane());
		// Resolve the player's tile on the client thread and pass it explicitly as "start"
		// so Shortest Path doesn't have to call client.getLocalPlayer() from whichever
		// thread it dispatches the PluginMessage on.
		clientThread.invoke(() ->
		{
			Player local = client.getLocalPlayer();
			if (local == null)
			{
				return;
			}
			Map<String, Object> data = new HashMap<>();
			data.put(SHORTEST_PATH_KEY_START, local.getWorldLocation());
			data.put(SHORTEST_PATH_KEY_TARGET, target);
			eventBus.post(new PluginMessage(SHORTEST_PATH_NAMESPACE, SHORTEST_PATH_MSG_PATH, data));
		});
	}

	private void clearShortestPath()
	{
		if (!isShortestPathInstalled())
		{
			return;
		}
		clientThread.invoke(() ->
			eventBus.post(new PluginMessage(SHORTEST_PATH_NAMESPACE, SHORTEST_PATH_MSG_CLEAR)));
	}

	// Toggle the Shortest Path integration via the same config key the settings
	// pane writes to. onConfigChanged handles installation check, send/clear,
	// and the "plugin not installed" warning dialog.
	public boolean isPathTrackingEnabled()
	{
		return config.useShortestPath();
	}

	public void togglePathTracking()
	{
		configManager.setConfiguration(GIMProgressTrackerConfig.GROUP, "useShortestPath",
			!config.useShortestPath());
	}

	private void openWikiForQuest(String questName)
	{
		String encoded = questName.replace(" ", "_").replace("'", "%27");
		LinkBrowser.browse("https://oldschool.runescape.wiki/w/" + encoded);
	}

	private void openQuestHelperForQuest(String questName)
	{
		// RuneLite's ClientUI.openPanel is package-private so we can't call it directly.
		// Best effort: copy the quest name to the clipboard so the user can paste it
		// into Quest Helper's search box, and show a notification as a nudge.
		Toolkit.getDefaultToolkit()
			.getSystemClipboard()
			.setContents(new StringSelection(questName), null);
		notifier.notify("Vibe Steps: search for \"" + questName + "\" in Quest Helper");
	}

	private String currentPlayerName()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}
		String name = local.getName();
		return (name == null || name.isEmpty()) ? null : name;
	}

	private static BufferedImage buildMapPointIcon(Color base)
	{
		int size = 18;
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(base);
			g.fillOval(2, 2, size - 4, size - 4);
			g.setColor(Color.BLACK);
			g.drawOval(2, 2, size - 5, size - 5);
			g.setColor(Color.WHITE);
			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
			g.drawString("!", size / 2 - 2, size / 2 + 4);
		}
		finally
		{
			g.dispose();
		}
		return img;
	}
}

package com.gimprogresstracker;

import com.gimprogresstracker.model.Chapter;
import com.gimprogresstracker.model.Guide;
import com.gimprogresstracker.model.PlayerProgress;
import com.gimprogresstracker.model.Section;
import com.gimprogresstracker.model.Step;
import com.gimprogresstracker.model.StepEntry;
import com.gimprogresstracker.util.ProgressStore;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Holds the active guide + the local player's progress and exposes mutation methods.
 *
 * Listeners are notified on every state change so the panel and overlays can refresh
 * without polling.
 */
@Slf4j
@Singleton
public class ProgressTracker
{
	private final ProgressStore progressStore;

	@Nullable
	private Guide guide;
	private List<StepEntry> flattened = Collections.emptyList();

	@Nullable
	private PlayerProgress progress;

	@Nullable
	private String playerName;

	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

	@Inject
	public ProgressTracker(ProgressStore progressStore)
	{
		this.progressStore = progressStore;
	}

	public void addListener(Runnable l)
	{
		listeners.add(l);
	}

	public void removeListener(Runnable l)
	{
		listeners.remove(l);
	}

	private void fire()
	{
		for (Runnable l : listeners)
		{
			try
			{
				l.run();
			}
			catch (Exception e)
			{
				log.debug("Listener threw", e);
			}
		}
	}

	public void setPlayerName(@Nullable String name)
	{
		if (java.util.Objects.equals(this.playerName, name))
		{
			return;
		}
		this.playerName = name;
		if (name != null && guide != null)
		{
			this.progress = progressStore.loadOrCreate(name, guide.getGuideName());
		}
		fire();
	}

	@Nullable
	public String getPlayerName()
	{
		return playerName;
	}

	public void setGuide(@Nullable Guide newGuide)
	{
		this.guide = newGuide;
		this.flattened = newGuide == null ? Collections.emptyList() : flatten(newGuide);
		if (newGuide != null && playerName != null)
		{
			this.progress = progressStore.loadOrCreate(playerName, newGuide.getGuideName());
		}
		else if (newGuide == null)
		{
			this.progress = null;
		}
		fire();
	}

	@Nullable
	public Guide getGuide()
	{
		return guide;
	}

	public List<StepEntry> getAllSteps()
	{
		return flattened;
	}

	@Nullable
	public PlayerProgress getProgress()
	{
		return progress;
	}

	public int getCompletedCount()
	{
		return progress == null ? 0 : progress.getCompletedStepIds().size();
	}

	public int getSkippedCount()
	{
		return progress == null ? 0 : progress.getSkippedStepIds().size();
	}

	public int getTotalCount()
	{
		return flattened.size();
	}

	public boolean isCompleted(int stepId)
	{
		return progress != null && progress.getCompletedStepIds().contains(stepId);
	}

	public boolean isSkipped(int stepId)
	{
		return progress != null && progress.getSkippedStepIds().contains(stepId);
	}

	public boolean isTodo(int stepId)
	{
		return progress != null && progress.getTodoStepIds().contains(stepId);
	}

	public boolean isResolved(int stepId)
	{
		return isCompleted(stepId) || isSkipped(stepId) || isTodo(stepId);
	}

	public int getTodoCount()
	{
		return progress == null ? 0 : progress.getTodoStepIds().size();
	}

	public List<StepEntry> getTodoSteps()
	{
		if (progress == null)
		{
			return Collections.emptyList();
		}
		List<StepEntry> out = new ArrayList<>();
		for (StepEntry e : flattened)
		{
			if (isTodo(e.getStep().getId()))
			{
				out.add(e);
			}
		}
		return out;
	}

	public Optional<StepEntry> getCurrentStep()
	{
		for (StepEntry e : flattened)
		{
			if (!isResolved(e.getStep().getId()))
			{
				return Optional.of(e);
			}
		}
		return Optional.empty();
	}

	public Optional<StepEntry> getCurrentStepFor(com.gimprogresstracker.model.PlayerProgress p)
	{
		if (p == null || flattened.isEmpty())
		{
			return Optional.empty();
		}
		java.util.Set<Integer> completed = p.getCompletedStepIds();
		java.util.Set<Integer> skipped = p.getSkippedStepIds();
		java.util.Set<Integer> todo = p.getTodoStepIds();
		for (StepEntry e : flattened)
		{
			int id = e.getStep().getId();
			if (!completed.contains(id) && !skipped.contains(id) && !todo.contains(id))
			{
				return Optional.of(e);
			}
		}
		return Optional.empty();
	}

	public List<StepEntry> getUpcoming(int max)
	{
		List<StepEntry> out = new ArrayList<>();
		boolean foundCurrent = false;
		for (StepEntry e : flattened)
		{
			if (!foundCurrent)
			{
				if (isResolved(e.getStep().getId()))
				{
					continue;
				}
				foundCurrent = true;
				continue; // skip the current step itself; we render it separately
			}
			if (isResolved(e.getStep().getId()))
			{
				continue;
			}
			out.add(e);
			if (out.size() >= max)
			{
				break;
			}
		}
		return out;
	}

	public void markCompleted(int stepId)
	{
		if (progress == null)
		{
			return;
		}
		progress.getSkippedStepIds().remove(stepId);
		progress.getTodoStepIds().remove(stepId);
		if (progress.getCompletedStepIds().add(stepId))
		{
			persist();
			fire();
		}
	}

	public void markSkipped(int stepId)
	{
		if (progress == null)
		{
			return;
		}
		progress.getCompletedStepIds().remove(stepId);
		progress.getTodoStepIds().remove(stepId);
		if (progress.getSkippedStepIds().add(stepId))
		{
			persist();
			fire();
		}
	}

	public void moveToPreviousStep()
	{
		if (progress == null)
		{
			return;
		}
		// Find the current step's position in the flattened list.
		int currentIndex = flattened.size();
		Optional<StepEntry> current = getCurrentStep();
		if (current.isPresent())
		{
			int currentId = current.get().getStep().getId();
			for (int i = 0; i < flattened.size(); i++)
			{
				if (flattened.get(i).getStep().getId() == currentId)
				{
					currentIndex = i;
					break;
				}
			}
		}
		// Walk backwards and unmark the nearest completed or skipped step.
		for (int i = currentIndex - 1; i >= 0; i--)
		{
			int stepId = flattened.get(i).getStep().getId();
			if (isCompleted(stepId) || isSkipped(stepId))
			{
				unmark(stepId);
				return;
			}
		}
	}

	public void markTodo(int stepId)
	{
		if (progress == null)
		{
			return;
		}
		progress.getCompletedStepIds().remove(stepId);
		progress.getSkippedStepIds().remove(stepId);
		if (progress.getTodoStepIds().add(stepId))
		{
			persist();
			fire();
		}
	}

	public void unmark(int stepId)
	{
		if (progress == null)
		{
			return;
		}
		boolean changed = progress.getCompletedStepIds().remove(stepId);
		changed |= progress.getSkippedStepIds().remove(stepId);
		changed |= progress.getTodoStepIds().remove(stepId);
		if (changed)
		{
			persist();
			fire();
		}
	}

	public void reset()
	{
		if (progress == null)
		{
			return;
		}
		progress.getCompletedStepIds().clear();
		progress.getSkippedStepIds().clear();
		progress.getTodoStepIds().clear();
		persist();
		fire();
	}

	public void persist()
	{
		if (progress != null && playerName != null)
		{
			progressStore.save(progress);
		}
	}

	private static List<StepEntry> flatten(Guide guide)
	{
		List<StepEntry> out = new ArrayList<>();
		int global = 0;
		List<Chapter> chapters = guide.getChapters();
		for (int ci = 0; ci < chapters.size(); ci++)
		{
			Chapter chapter = chapters.get(ci);
			List<Section> sections = chapter.getSections();
			for (int si = 0; si < sections.size(); si++)
			{
				Section section = sections.get(si);
				List<Step> steps = section.getSteps();
				for (int sti = 0; sti < steps.size(); sti++)
				{
					Step step = steps.get(sti);
					out.add(new StepEntry(ci, si, sti, global++, chapter, section, step));
				}
			}
		}
		return out;
	}
}

