		add(complete);

		add(Box.createVerticalStrut(4));

		JPanel navRow = new JPanel();
		navRow.setLayout(new BoxLayout(navRow, BoxLayout.X_AXIS));
		navRow.setOpaque(false);
		navRow.setAlignmentX(Component.LEFT_ALIGNMENT);

