		navRow.add(Box.createHorizontalStrut(4));

		JButton skip = styledButton("Skip →", ColorScheme.LIGHT_GRAY_COLOR, SECONDARY_BTN_BG, SECONDARY_BTN_HOVER, ColorScheme.MEDIUM_GRAY_COLOR);
