	}

	private static String formatLastUpdated(String iso)
	{
		if (iso == null || iso.isEmpty())
		{
			return "Last updated: unknown";
		}
		try
		{
			Instant then = Instant.parse(iso);
			Duration ago = Duration.between(then, Instant.now());
			long mins = ago.toMinutes();
			if (mins < 1)
			{
				return "Updated just now";
			}
			if (mins < 60)
			{
				return "Updated " + mins + " min ago";
			}
			long hours = ago.toHours();
			if (hours < 24)
			{
				return "Updated " + hours + "h ago";
			}
			return "Updated " + ago.toDays() + "d ago";
		}
		catch (Exception e)
		{
			return "Last updated: " + iso;
		}
	}

	private static String firstWords(String text, int max)
	{
		if (text == null)
		{
			return "";
		}
		String flat = text.replace('\n', ' ').trim();
		String[] words = flat.split("\\s+");
		if (words.length <= max)
		{
			return flat;
		}
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < max; i++)
		{
			if (i > 0)
			{
				sb.append(' ');
			}
			sb.append(words[i]);
		}
		sb.append("…");
		return sb.toString();
	}
}

package com.gimprogresstracker.util;

import com.gimprogresstracker.model.Chapter;
import com.gimprogresstracker.model.Guide;
import com.gimprogresstracker.model.Section;
import com.gimprogresstracker.model.Step;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class GuideImporter
{
	private final Gson gson;

	@Inject
	public GuideImporter(Gson gson)
	{
		this.gson = gson;
	}

	public Guide loadFromFile(Path path) throws IOException
	{
		try (Reader reader = Files.newBufferedReader(path, StandardCharsets.UTF_8))
		{
			return parse(reader);
		}
	}

	public Guide loadFromResource(String resourcePath) throws IOException
	{
		InputStream stream = GuideImporter.class.getResourceAsStream(resourcePath);
		if (stream == null)
		{
			throw new IOException("Bundled guide resource not found: " + resourcePath);
		}
		try (Reader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
		{
			return parse(reader);
		}
	}

	private Guide parse(Reader reader) throws IOException
	{
		try
		{
			Guide guide = gson.fromJson(reader, Guide.class);
			if (guide == null)
			{
				throw new IOException("Guide file is empty or malformed");
			}
			validate(guide);
			return guide;
		}
		catch (JsonParseException e)
		{
			throw new IOException("Failed to parse guide JSON: " + e.getMessage(), e);
		}
	}

	private void validate(Guide guide) throws IOException
	{
		if (guide.getGuideName() == null || guide.getGuideName().isEmpty())
		{
			throw new IOException("Guide is missing 'guideName'");
		}
		if (guide.getChapters().isEmpty())
		{
			throw new IOException("Guide has no chapters");
		}

		Set<Integer> seenIds = new HashSet<>();
		int totalSteps = 0;
		for (Chapter chapter : guide.getChapters())
		{
			for (Section section : chapter.getSections())
			{
				for (Step step : section.getSteps())
				{
					totalSteps++;
					if (!seenIds.add(step.getId()))
					{
						throw new IOException("Duplicate step id in guide: " + step.getId());
					}
					if (step.getDescription() == null || step.getDescription().isEmpty())
					{
						throw new IOException("Step " + step.getId() + " has no description");
					}
				}
			}
		}
		if (totalSteps == 0)
		{
			throw new IOException("Guide contains no steps");
		}
		log.debug("Loaded guide '{}' with {} steps", guide.getGuideName(), totalSteps);
	}
}

package com.gimprogresstracker.util;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import net.runelite.client.RuneLite;

public final class PluginPaths
{
	private static final String PLUGIN_DIR = "gim-progress-tracker";

	private PluginPaths()
	{
	}

	public static Path baseDir()
	{
		return RuneLite.RUNELITE_DIR.toPath().resolve(PLUGIN_DIR);
	}

	public static Path progressDir() throws IOException
	{
		return ensure(baseDir().resolve("progress"));
	}

	public static Path guidesDir() throws IOException
	{
		return ensure(baseDir().resolve("guides"));
	}

	public static Path teammatesDir() throws IOException
	{
		return ensure(baseDir().resolve("teammates"));
	}

	private static Path ensure(Path p) throws IOException
	{
		if (!Files.isDirectory(p))
		{
			Files.createDirectories(p);
		}
		return p;
	}

	/**
	 * Replace OS-illegal filename characters so a player name can be used as a filename safely.
	 */
	public static String sanitizeForFilename(String name)
	{
		if (name == null || name.isEmpty())
		{
			return "unknown";
		}
		return name.replaceAll("[^A-Za-z0-9._-]", "_");
	}
}

package com.gimprogresstracker.util;

import com.gimprogresstracker.model.PlayerProgress;
import com.gimprogresstracker.model.TeammateProgress;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class ProgressStore
{
	private final Gson gson;

	@Inject
	public ProgressStore(Gson gson)
	{
		this.gson = gson;
	}

	public PlayerProgress loadOrCreate(String playerName, String guideName)
	{
		Path file;
		try
		{
			file = progressFile(playerName);
		}
		catch (IOException e)
		{
			log.warn("Could not resolve progress directory", e);
			return blank(playerName, guideName);
		}

		if (!Files.isRegularFile(file))
		{
			return blank(playerName, guideName);
		}

		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			PlayerProgress progress = gson.fromJson(reader, PlayerProgress.class);
			if (progress == null)
			{
				return blank(playerName, guideName);
			}
			// If the saved progress is for a different guide, start fresh — completion IDs
			// only have meaning within the guide they were collected in.
			if (guideName != null && !guideName.equals(progress.getGuideName()))
			{
				return blank(playerName, guideName);
			}
			progress.setPlayerName(playerName);
			return progress;
		}
		catch (IOException | JsonParseException e)
		{
			log.warn("Failed to read progress file {}", file, e);
			return blank(playerName, guideName);
		}
	}

	public void save(PlayerProgress progress)
	{
		if (progress.getPlayerName() == null || progress.getPlayerName().isEmpty())
		{
			return;
		}
		progress.setLastUpdated(Instant.now().toString());

		Path file;
		try
		{
			file = progressFile(progress.getPlayerName());
		}
		catch (IOException e)
		{
			log.warn("Could not resolve progress directory", e);
			return;
		}

		try (Writer writer = Files.newBufferedWriter(file, StandardCharsets.UTF_8))
		{
			gson.toJson(progress, writer);
		}
		catch (IOException e)
		{
			log.warn("Failed to write progress file {}", file, e);
		}
	}

	public void exportTo(PlayerProgress progress, Path target) throws IOException
	{
		progress.setLastUpdated(Instant.now().toString());
		try (Writer writer = Files.newBufferedWriter(target, StandardCharsets.UTF_8))
		{
			gson.toJson(progress, writer);
		}
	}

	public TeammateProgress readTeammate(Path file) throws IOException
	{
		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			TeammateProgress tp = gson.fromJson(reader, TeammateProgress.class);
			if (tp == null)
			{
				throw new IOException("Teammate progress file is empty");
			}
			return tp;
		}
		catch (JsonParseException e)
		{
			throw new IOException("Malformed teammate progress JSON: " + e.getMessage(), e);
		}
	}

	public PlayerProgress readPlayerProgress(Path file) throws IOException
	{
		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			PlayerProgress p = gson.fromJson(reader, PlayerProgress.class);
			if (p == null)
			{
				throw new IOException("Progress file is empty");
			}
			return p;
		}
		catch (JsonParseException e)
		{
			throw new IOException("Malformed progress JSON: " + e.getMessage(), e);
		}
	}

	private Path progressFile(String playerName) throws IOException
	{
		return PluginPaths.progressDir().resolve(PluginPaths.sanitizeForFilename(playerName) + "_progress.json");
	}

	private PlayerProgress blank(String playerName, String guideName)
	{
		PlayerProgress p = new PlayerProgress();
		p.setPlayerName(playerName);
		p.setGuideName(guideName);
		return p;
	}
}

